import { el } from "./docs";
import { icon } from "./icon";
import { publicUrl } from "./url";

type AgentFile = { label: string; href: string; note: string };

/**
 * "For AI agents & tools": links to the machine-readable versions of the
 * current page (generated by `npm run tokens`). Figma 313:4597: a panel in
 * the bottom-right corner, opened by the globe button next to the Theme
 * switch (markup in index.html, styles .corner / .agent-links in layout.css).
 */
function panel() {
  return document.getElementById("agent-panel");
}

/** Fills the panel with this page's files (always ending with llms.txt). */
export function setAgentLinks(files: AgentFile[]) {
  const box = panel();
  if (!box) return;

  const header = el("div", "agent-links__header");
  const title = el("h2", "agent-links__title text-body-large-strong", "For AI agents & tools");
  title.id = "agent-links-title";
  header.append(icon("internet", 16), title);

  const text = el("p", "agent-links__text text-body-large");
  text.append("Machine-readable versions of this page: ");
  for (const file of files) {
    const link = el("a", undefined, file.label);
    link.href = file.href;
    text.append(link, ` (${file.note}) · `);
  }
  const llms = el("a", undefined, "llms.txt");
  llms.href = publicUrl("llms.txt");
  text.append(llms);

  box.replaceChildren(header, text);
}

/**
 * For pages: sets the corner panel's files and returns an empty marker, so
 * `body.append(…, agentLinks(files))` keeps working without adding a block
 * to the page.
 */
export function agentLinks(files: AgentFile[]): Node {
  setAgentLinks(files);
  return document.createComment(" For AI agents & tools: in the corner panel ");
}

/**
 * The globe button opens and closes the panel above it. It closes on
 * Escape (focus returns to the button) and on a click anywhere else.
 * Opening from the keyboard is instant; from the pointer it scales in from
 * the button's corner (CSS).
 */
export function initAgentPanel(toggle: HTMLButtonElement, corner: HTMLElement) {
  const box = panel();
  if (!box) return;

  const isOpen = () => toggle.getAttribute("aria-expanded") === "true";
  function setOpen(open: boolean, instant = false) {
    toggle.setAttribute("aria-expanded", String(open));
    box!.toggleAttribute("inert", !open);
    box!.toggleAttribute("data-instant", instant);
    corner.toggleAttribute("data-open", open);
  }

  // detail is 0 for clicks synthesized from Enter / Space.
  toggle.addEventListener("click", (event) => setOpen(!isOpen(), event.detail === 0));

  document.addEventListener("keydown", (event) => {
    if (event.key !== "Escape" || !isOpen()) return;
    const hadFocus = corner.contains(document.activeElement);
    setOpen(false, true);
    if (hadFocus) toggle.focus();
  });

  document.addEventListener("pointerdown", (event) => {
    if (isOpen() && !corner.contains(event.target as Node)) setOpen(false);
  });
}

export const COLOR_TOKENS_FILE = {
  label: "colors.json",
  href: publicUrl("tokens/colors.json"),
  note: "design tokens with light/dark values and usage rules",
};

export const TYPOGRAPHY_TOKENS_FILE = {
  label: "typography.json",
  href: publicUrl("tokens/typography.json"),
  note: "design tokens with usage rules",
};
